    assessmentTools: { rubric: ['دليل للموقفين', '«كان» + مضارع و«عَلَّمَ/تَعَلَّمَ»', 'المقارنة ونقل الرأي', 'النقل المحترم'], exitTicket: ['أكمل واضبط: «رَأَتِ الْمَلَائِكَةُ أَنَّ آدَمَ ____، لَكِنَّ إِبْلِيسَ ____».'] }
